import numpy as np

def find_solutions():
    solutions = []
    # d = [ (198e - 18) +/- sqrt(-8316e^2 + 16632e - 1116) ] / 180
    for e in np.linspace(0.07, 1.0, 2000):
        disc = -8316*e**2 + 16632*e - 1116
        if disc >= 0:
            d1 = (198*e - 18 + np.sqrt(disc)) / 180
            d2 = (198*e - 18 - np.sqrt(disc)) / 180
            for d in [d1, d2]:
                if 0 <= d <= 1:
                    S = 2 + 9*d - 11*e
                    if -1 < S < 1:
                        solutions.append((e, d, S))
    return solutions

sols = find_solutions()
print(f"Found {len(sols)} solutions.")
if sols:
    print(f"Example solution: {sols[0]}")
else:
    print("No solutions found in this range.")

